// Command api serves the Coach sync API.
//
// Configuration comes from the environment:
//
//	DATABASE_URL     Postgres connection string (required)
//	COACH_API_TOKEN  bearer token clients must send, at least 32 chars (required)
//	LISTEN_ADDR      address to listen on (default ":8080")
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"coach/server/internal/api"
	"coach/server/internal/db"
	"coach/server/internal/store"

	"github.com/jackc/pgx/v5/pgxpool"
)

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	if err := run(log); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger) error {
	dbURL := os.Getenv("DATABASE_URL")
	token := os.Getenv("COACH_API_TOKEN")
	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = ":8080"
	}
	if dbURL == "" {
		return errors.New("DATABASE_URL is required")
	}
	if len(token) < 32 {
		return errors.New("COACH_API_TOKEN must be at least 32 characters")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	pool, err := connectWithRetry(ctx, dbURL, log)
	if err != nil {
		return err
	}
	defer pool.Close()
	if err := db.Migrate(ctx, pool); err != nil {
		return err
	}

	srv := &http.Server{
		Addr:              addr,
		Handler:           api.New(store.New(pool), token, log),
		ReadHeaderTimeout: 10 * time.Second,
	}
	errc := make(chan error, 1)
	go func() { errc <- srv.ListenAndServe() }()
	log.Info("listening", "addr", addr)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}

// connectWithRetry waits for Postgres, which may still be starting when the
// container comes up.
func connectWithRetry(ctx context.Context, url string, log *slog.Logger) (*pgxpool.Pool, error) {
	var lastErr error
	for attempt := 1; attempt <= 30; attempt++ {
		pool, err := db.Connect(ctx, url)
		if err == nil {
			return pool, nil
		}
		lastErr = err
		log.Warn("database not ready", "attempt", attempt, "err", err)
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(2 * time.Second):
		}
	}
	return nil, lastErr
}

// Package api is the HTTP layer: auth, request decoding and routing.
package api

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"strconv"
	"strings"

	"coach/server/internal/store"
)

const (
	maxBodyBytes     = 5 << 20
	defaultPullLimit = 500
	maxPullLimit     = 2000
)

// Syncer is the storage the handlers need; *store.Store implements it.
type Syncer interface {
	Push(ctx context.Context, c store.Changes) (store.PushResult, error)
	Pull(ctx context.Context, since int64, limit int) (store.PullResult, error)
}

// New returns the API handler. Every /v1 route requires the bearer token.
func New(s Syncer, token string, log *slog.Logger) http.Handler {
	h := &handlers{s: s, log: log}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})

	v1 := http.NewServeMux()
	v1.HandleFunc("POST /v1/sync/push", h.push)
	v1.HandleFunc("GET /v1/sync/pull", h.pull)
	mux.Handle("/v1/", requireToken(token, v1))
	return mux
}

type handlers struct {
	s   Syncer
	log *slog.Logger
}

func (h *handlers) push(w http.ResponseWriter, r *http.Request) {
	var c store.Changes
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&c); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON: "+err.Error())
		return
	}
	res, err := h.s.Push(r.Context(), c)
	if err != nil {
		h.fail(w, err)
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (h *handlers) pull(w http.ResponseWriter, r *http.Request) {
	since, err := intParam(r, "since", 0)
	if err != nil || since < 0 {
		writeError(w, http.StatusBadRequest, "since must be a non-negative integer")
		return
	}
	limit, err := intParam(r, "limit", defaultPullLimit)
	if err != nil || limit < 1 || limit > maxPullLimit {
		writeError(w, http.StatusBadRequest, "limit must be between 1 and 2000")
		return
	}
	res, err := h.s.Pull(r.Context(), since, int(limit))
	if err != nil {
		h.fail(w, err)
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (h *handlers) fail(w http.ResponseWriter, err error) {
	var ve store.ValidationError
	if errors.As(err, &ve) {
		writeError(w, http.StatusBadRequest, ve.Error())
		return
	}
	h.log.Error("request failed", "err", err)
	writeError(w, http.StatusInternalServerError, "internal error")
}

func requireToken(token string, next http.Handler) http.Handler {
	want := []byte("Bearer " + token)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		got := []byte(r.Header.Get("Authorization"))
		if subtle.ConstantTimeCompare(got, want) != 1 {
			writeError(w, http.StatusUnauthorized, "missing or invalid token")
			return
		}
		next.ServeHTTP(w, r)
	})
}

func intParam(r *http.Request, name string, def int64) (int64, error) {
	v := strings.TrimSpace(r.URL.Query().Get(name))
	if v == "" {
		return def, nil
	}
	return strconv.ParseInt(v, 10, 64)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

// Package store implements the sync protocol on top of Postgres.
//
// Clients push batches of changed records and pull everything with a
// server_seq above their cursor. Each entity type gets its own table and its
// own field in Changes; adding a type means adding a migration, a struct with
// upsert/pull functions, and wiring it into Push and Pull below.
package store

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Origins a record can come from.
var validOrigins = map[string]bool{"phone": true, "watch": true, "web": true, "mcp": true}

var uuidRe = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

// Changes is a set of records grouped by entity type.
type Changes struct {
	Fasts []Fast `json:"fasts"`
}

// PushResult says which records were written and which were skipped because
// the server already had an equal or newer version.
type PushResult struct {
	Applied []string `json:"applied"`
	Stale   []string `json:"stale"`
}

// PullResult is one page of changes. Cursor is the value to send as "since"
// on the next pull.
type PullResult struct {
	Changes Changes `json:"changes"`
	Cursor  int64   `json:"cursor"`
	HasMore bool    `json:"has_more"`
}

// ValidationError marks a request the client must fix; the API maps it to 400.
type ValidationError struct{ msg string }

func (e ValidationError) Error() string { return e.msg }

type querier interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

// Store is the Postgres-backed sync store.
type Store struct {
	pool *pgxpool.Pool
}

func New(pool *pgxpool.Pool) *Store { return &Store{pool: pool} }

// Validate checks every record in the batch before anything is written.
func (c Changes) Validate() error {
	for i, f := range c.Fasts {
		if err := f.Validate(); err != nil {
			return ValidationError{fmt.Sprintf("fasts[%d]: %v", i, err)}
		}
	}
	return nil
}

// Push writes a batch atomically.
func (s *Store) Push(ctx context.Context, c Changes) (PushResult, error) {
	if err := c.Validate(); err != nil {
		return PushResult{}, err
	}
	res := PushResult{Applied: []string{}, Stale: []string{}}

	err := pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		// Serialize writers so server_seq values become visible in order;
		// otherwise a puller could advance past a seq still being committed.
		if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock(1)`); err != nil {
			return err
		}
		for _, f := range c.Fasts {
			ok, err := upsertFast(ctx, tx, f)
			if err != nil {
				return err
			}
			if ok {
				res.Applied = append(res.Applied, f.ID)
			} else {
				res.Stale = append(res.Stale, f.ID)
			}
		}
		return nil
	})
	if err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23514" { // check_violation
			return PushResult{}, ValidationError{pgErr.Message}
		}
		return PushResult{}, err
	}
	return res, nil
}

// Pull returns up to limit records changed after since, across all types,
// in server_seq order.
func (s *Store) Pull(ctx context.Context, since int64, limit int) (PullResult, error) {
	// Fetch limit+1 from each table so we can tell whether more remain.
	fasts, err := pullFasts(ctx, s.pool, since, limit+1)
	if err != nil {
		return PullResult{}, err
	}

	type seqer interface{ seq() int64 }
	var all []seqer
	for _, f := range fasts {
		all = append(all, f)
	}
	sort.Slice(all, func(i, j int) bool { return all[i].seq() < all[j].seq() })

	res := PullResult{Changes: Changes{Fasts: []Fast{}}, Cursor: since}
	if len(all) > limit {
		all = all[:limit]
		res.HasMore = true
	}
	for _, r := range all {
		switch v := r.(type) {
		case Fast:
			res.Changes.Fasts = append(res.Changes.Fasts, v)
		}
		res.Cursor = r.seq()
	}
	return res, nil
}

func validateMeta(id string, created, updated time.Time, origin string) error {
	if !uuidRe.MatchString(id) {
		return errors.New("id must be a UUID")
	}
	if created.IsZero() || updated.IsZero() {
		return errors.New("created_at and updated_at are required")
	}
	if updated.Before(created) {
		return errors.New("updated_at is before created_at")
	}
	if !validOrigins[origin] {
		return fmt.Errorf("unknown origin %q", origin)
	}
	return nil
}

package store

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
)

// Fast is one fasting period. EndedAt is nil while the fast is running.
type Fast struct {
	ID          string     `json:"id"`
	StartedAt   time.Time  `json:"started_at"`
	EndedAt     *time.Time `json:"ended_at"`
	GoalSeconds int        `json:"goal_seconds"`
	Notes       string     `json:"notes"`
	CreatedAt   time.Time  `json:"created_at"`
	UpdatedAt   time.Time  `json:"updated_at"`
	DeletedAt   *time.Time `json:"deleted_at"`
	Origin      string     `json:"origin"`
	ServerSeq   int64      `json:"server_seq,omitempty"`
}

func (f Fast) seq() int64 { return f.ServerSeq }

// Validate checks the fields a client is responsible for.
func (f Fast) Validate() error {
	if err := validateMeta(f.ID, f.CreatedAt, f.UpdatedAt, f.Origin); err != nil {
		return err
	}
	if f.StartedAt.IsZero() {
		return errors.New("started_at is required")
	}
	if f.EndedAt != nil && f.EndedAt.Before(f.StartedAt) {
		return errors.New("ended_at is before started_at")
	}
	if f.GoalSeconds <= 0 {
		return errors.New("goal_seconds must be positive")
	}
	return nil
}

// upsertFast writes f unless the stored row is as new or newer
// (last-writer-wins on updated_at). It reports whether the row was written.
func upsertFast(ctx context.Context, tx pgx.Tx, f Fast) (bool, error) {
	tag, err := tx.Exec(ctx, `
		INSERT INTO fasts (id, started_at, ended_at, goal_seconds, notes,
		                   created_at, updated_at, deleted_at, origin)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
		ON CONFLICT (id) DO UPDATE SET
			started_at   = EXCLUDED.started_at,
			ended_at     = EXCLUDED.ended_at,
			goal_seconds = EXCLUDED.goal_seconds,
			notes        = EXCLUDED.notes,
			updated_at   = EXCLUDED.updated_at,
			deleted_at   = EXCLUDED.deleted_at,
			origin       = EXCLUDED.origin,
			server_seq   = nextval('sync_seq')
		WHERE fasts.updated_at < EXCLUDED.updated_at`,
		f.ID, f.StartedAt, f.EndedAt, f.GoalSeconds, f.Notes,
		f.CreatedAt, f.UpdatedAt, f.DeletedAt, f.Origin)
	if err != nil {
		return false, fmt.Errorf("upsert fast %s: %w", f.ID, err)
	}
	return tag.RowsAffected() == 1, nil
}

func pullFasts(ctx context.Context, q querier, since int64, limit int) ([]Fast, error) {
	rows, err := q.Query(ctx, `
		SELECT id::text, started_at, ended_at, goal_seconds, notes,
		       created_at, updated_at, deleted_at, origin, server_seq
		FROM fasts
		WHERE server_seq > $1
		ORDER BY server_seq
		LIMIT $2`, since, limit)
	if err != nil {
		return nil, fmt.Errorf("pull fasts: %w", err)
	}
	return pgx.CollectRows(rows, func(r pgx.CollectableRow) (Fast, error) {
		var f Fast
		err := r.Scan(&f.ID, &f.StartedAt, &f.EndedAt, &f.GoalSeconds, &f.Notes,
			&f.CreatedAt, &f.UpdatedAt, &f.DeletedAt, &f.Origin, &f.ServerSeq)
		return f, err
	})
}

// Package db owns the Postgres connection pool and schema migrations.
package db

import (
	"context"
	"embed"
	"fmt"
	"io/fs"
	"sort"
	"strings"

	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed migrations/*.sql
var migrationFS embed.FS

// Connect opens a pool and verifies the database is reachable.
func Connect(ctx context.Context, url string) (*pgxpool.Pool, error) {
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return nil, fmt.Errorf("open pool: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping: %w", err)
	}
	return pool, nil
}

// Migration is one embedded SQL file, applied in filename order.
type Migration struct {
	Name string
	SQL  string
}

// Migrations returns the embedded migrations sorted by filename.
func Migrations() ([]Migration, error) {
	entries, err := fs.ReadDir(migrationFS, "migrations")
	if err != nil {
		return nil, err
	}
	var out []Migration
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".sql") {
			continue
		}
		body, err := migrationFS.ReadFile("migrations/" + e.Name())
		if err != nil {
			return nil, err
		}
		out = append(out, Migration{Name: e.Name(), SQL: string(body)})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// Migrate applies any migrations not yet recorded in schema_migrations.
// Each migration runs in its own transaction.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	if _, err := pool.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		name       text PRIMARY KEY,
		applied_at timestamptz NOT NULL DEFAULT now()
	)`); err != nil {
		return fmt.Errorf("create schema_migrations: %w", err)
	}

	migrations, err := Migrations()
	if err != nil {
		return err
	}
	for _, m := range migrations {
		var applied bool
		if err := pool.QueryRow(ctx,
			`SELECT EXISTS (SELECT 1 FROM schema_migrations WHERE name = $1)`, m.Name,
		).Scan(&applied); err != nil {
			return fmt.Errorf("check %s: %w", m.Name, err)
		}
		if applied {
			continue
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, m.SQL); err != nil {
			tx.Rollback(ctx)
			return fmt.Errorf("apply %s: %w", m.Name, err)
		}
		if _, err := tx.Exec(ctx, `INSERT INTO schema_migrations (name) VALUES ($1)`, m.Name); err != nil {
			tx.Rollback(ctx)
			return fmt.Errorf("record %s: %w", m.Name, err)
		}
		if err := tx.Commit(ctx); err != nil {
			return fmt.Errorf("commit %s: %w", m.Name, err)
		}
	}
	return nil
}

package api

import (
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"coach/server/internal/store"
)

const testToken = "test-token-0123456789-0123456789-abcdef"

type fakeSyncer struct {
	pushed    store.Changes
	pushErr   error
	pullSince int64
	pullLimit int
}

func (f *fakeSyncer) Push(_ context.Context, c store.Changes) (store.PushResult, error) {
	f.pushed = c
	if f.pushErr != nil {
		return store.PushResult{}, f.pushErr
	}
	return store.PushResult{Applied: []string{"a"}, Stale: []string{}}, nil
}

func (f *fakeSyncer) Pull(_ context.Context, since int64, limit int) (store.PullResult, error) {
	f.pullSince, f.pullLimit = since, limit
	return store.PullResult{Changes: store.Changes{Fasts: []store.Fast{}}, Cursor: since}, nil
}

func newTestServer(t *testing.T, s Syncer) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(New(s, testToken, slog.New(slog.NewTextHandler(io.Discard, nil))))
	t.Cleanup(srv.Close)
	return srv
}

func do(t *testing.T, method, url, token, body string) *http.Response {
	t.Helper()
	req, err := http.NewRequest(method, url, strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { resp.Body.Close() })
	return resp
}

func TestHealthzNeedsNoToken(t *testing.T) {
	srv := newTestServer(t, &fakeSyncer{})
	if resp := do(t, "GET", srv.URL+"/healthz", "", ""); resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
}

func TestSyncRequiresToken(t *testing.T) {
	srv := newTestServer(t, &fakeSyncer{})
	for _, tok := range []string{"", "wrong-token"} {
		if resp := do(t, "GET", srv.URL+"/v1/sync/pull", tok, ""); resp.StatusCode != http.StatusUnauthorized {
			t.Errorf("token %q: status = %d, want 401", tok, resp.StatusCode)
		}
	}
}

func TestPullParams(t *testing.T) {
	f := &fakeSyncer{}
	srv := newTestServer(t, f)

	resp := do(t, "GET", srv.URL+"/v1/sync/pull?since=42&limit=10", testToken, "")
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	if f.pullSince != 42 || f.pullLimit != 10 {
		t.Errorf("got since=%d limit=%d, want 42, 10", f.pullSince, f.pullLimit)
	}

	do(t, "GET", srv.URL+"/v1/sync/pull", testToken, "")
	if f.pullSince != 0 || f.pullLimit != defaultPullLimit {
		t.Errorf("defaults: got since=%d limit=%d", f.pullSince, f.pullLimit)
	}

	for _, q := range []string{"since=-1", "since=abc", "limit=0", "limit=5000"} {
		if resp := do(t, "GET", srv.URL+"/v1/sync/pull?"+q, testToken, ""); resp.StatusCode != http.StatusBadRequest {
			t.Errorf("%s: status = %d, want 400", q, resp.StatusCode)
		}
	}
}

func TestPushDecodesBody(t *testing.T) {
	f := &fakeSyncer{}
	srv := newTestServer(t, f)
	body := `{"fasts":[{"id":"7f1c5e3a-2b4d-4c6e-8f00-112233445566","started_at":"2026-10-27T16:30:00Z",
		"ended_at":null,"goal_seconds":57600,"notes":"","created_at":"2026-10-27T16:30:00Z",
		"updated_at":"2026-10-27T16:30:00Z","deleted_at":null,"origin":"phone"}]}`

	resp := do(t, "POST", srv.URL+"/v1/sync/push", testToken, body)
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	if len(f.pushed.Fasts) != 1 || f.pushed.Fasts[0].GoalSeconds != 57600 {
		t.Errorf("pushed = %+v", f.pushed)
	}
	var res store.PushResult
	if err := json.NewDecoder(resp.Body).Decode(&res); err != nil || len(res.Applied) != 1 {
		t.Errorf("response = %+v, err %v", res, err)
	}
}

func TestPushRejectsBadInput(t *testing.T) {
	srv := newTestServer(t, &fakeSyncer{})
	for name, body := range map[string]string{
		"malformed":     `{"fasts":[`,
		"unknown field": `{"workouts":[]}`,
	} {
		if resp := do(t, "POST", srv.URL+"/v1/sync/push", testToken, body); resp.StatusCode != http.StatusBadRequest {
			t.Errorf("%s: status = %d, want 400", name, resp.StatusCode)
		}
	}
}

func TestPushValidationErrorIs400(t *testing.T) {
	srv := newTestServer(t, &fakeSyncer{pushErr: store.ValidationError{}})
	if resp := do(t, "POST", srv.URL+"/v1/sync/push", testToken, `{"fasts":[]}`); resp.StatusCode != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", resp.StatusCode)
	}
}

package store

import (
	"context"
	"os"
	"testing"
	"time"

	"coach/server/internal/db"
)

var t0 = time.Date(2026, 10, 27, 16, 30, 0, 0, time.UTC)

func validFast() Fast {
	return Fast{
		ID:          "7f1c5e3a-2b4d-4c6e-8f00-112233445566",
		StartedAt:   t0,
		GoalSeconds: 16 * 3600,
		CreatedAt:   t0,
		UpdatedAt:   t0,
		Origin:      "phone",
	}
}

func TestFastValidate(t *testing.T) {
	before := t0.Add(-time.Hour)
	cases := map[string]func(*Fast){
		"bad id":           func(f *Fast) { f.ID = "not-a-uuid" },
		"no start":         func(f *Fast) { f.StartedAt = time.Time{} },
		"ends before":      func(f *Fast) { f.EndedAt = &before },
		"zero goal":        func(f *Fast) { f.GoalSeconds = 0 },
		"unknown origin":   func(f *Fast) { f.Origin = "fridge" },
		"updated<created":  func(f *Fast) { f.UpdatedAt = before },
		"missing metadata": func(f *Fast) { f.CreatedAt = time.Time{} },
	}
	if err := validFast().Validate(); err != nil {
		t.Fatalf("valid fast rejected: %v", err)
	}
	for name, mutate := range cases {
		f := validFast()
		mutate(&f)
		if err := f.Validate(); err == nil {
			t.Errorf("%s: expected error", name)
		}
	}
}

func TestMigrationsSorted(t *testing.T) {
	ms, err := db.Migrations()
	if err != nil || len(ms) == 0 {
		t.Fatalf("migrations: %v (n=%d)", err, len(ms))
	}
	for i := 1; i < len(ms); i++ {
		if ms[i-1].Name >= ms[i].Name {
			t.Errorf("out of order: %s, %s", ms[i-1].Name, ms[i].Name)
		}
	}
}

// TestSyncRoundTrip runs against a real, disposable Postgres database:
//
//	COACH_TEST_DATABASE_URL=postgres://... go test ./...
//
// It drops and recreates the schema, so never point it at real data.
func TestSyncRoundTrip(t *testing.T) {
	url := os.Getenv("COACH_TEST_DATABASE_URL")
	if url == "" {
		t.Skip("COACH_TEST_DATABASE_URL not set")
	}
	ctx := context.Background()
	pool, err := db.Connect(ctx, url)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Close()
	if _, err := pool.Exec(ctx, `DROP SCHEMA public CASCADE; CREATE SCHEMA public`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx, pool); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx, pool); err != nil {
		t.Fatalf("second migrate should be a no-op: %v", err)
	}
	s := New(pool)

	f := validFast()
	res, err := s.Push(ctx, Changes{Fasts: []Fast{f}})
	if err != nil || len(res.Applied) != 1 {
		t.Fatalf("first push: %+v, %v", res, err)
	}

	// Re-pushing the same version is stale, not an error.
	res, err = s.Push(ctx, Changes{Fasts: []Fast{f}})
	if err != nil || len(res.Stale) != 1 {
		t.Fatalf("repush: %+v, %v", res, err)
	}

	page, err := s.Pull(ctx, 0, 100)
	if err != nil || len(page.Changes.Fasts) != 1 {
		t.Fatalf("pull: %+v, %v", page, err)
	}
	cursor := page.Cursor

	// A newer edit wins and moves the row past the cursor.
	end := t0.Add(16 * time.Hour)
	f.EndedAt, f.UpdatedAt = &end, end
	if res, err := s.Push(ctx, Changes{Fasts: []Fast{f}}); err != nil || len(res.Applied) != 1 {
		t.Fatalf("update push: %+v, %v", res, err)
	}
	page, err = s.Pull(ctx, cursor, 100)
	if err != nil || len(page.Changes.Fasts) != 1 || page.Changes.Fasts[0].EndedAt == nil {
		t.Fatalf("pull after update: %+v, %v", page, err)
	}

	// An older edit loses.
	older := f
	older.UpdatedAt = t0.Add(time.Hour)
	older.Notes = "stale"
	if res, _ := s.Push(ctx, Changes{Fasts: []Fast{older}}); len(res.Stale) != 1 {
		t.Fatalf("older edit should be stale: %+v", res)
	}

	// Paging: three new rows, limit 2.
	var batch []Fast
	for _, id := range []string{
		"00000000-0000-4000-8000-000000000001",
		"00000000-0000-4000-8000-000000000002",
		"00000000-0000-4000-8000-000000000003",
	} {
		g := validFast()
		g.ID = id
		batch = append(batch, g)
	}
	if _, err := s.Push(ctx, Changes{Fasts: batch}); err != nil {
		t.Fatal(err)
	}
	page, _ = s.Pull(ctx, 0, 2)
	if len(page.Changes.Fasts) != 2 || !page.HasMore {
		t.Fatalf("page 1: %+v", page)
	}
	page, _ = s.Pull(ctx, page.Cursor, 2)
	if len(page.Changes.Fasts) != 2 || page.HasMore {
		t.Fatalf("page 2: %+v", page)
	}
}

import Foundation
import GRDB

/// The on-device SQLite database. Tables mirror the server's, plus two local
/// bookkeeping tables: `pending_change` (records not yet pushed) and
/// `sync_state` (the pull cursor and similar).
final class AppDatabase: Sendable {
    let writer: any DatabaseWriter

    init(_ writer: any DatabaseWriter) throws {
        self.writer = writer
        try Self.migrator.migrate(writer)
    }

    /// The app's database in Application Support.
    static func onDisk() throws -> AppDatabase {
        let dir = try FileManager.default.url(
            for: .applicationSupportDirectory, in: .userDomainMask,
            appropriateFor: nil, create: true)
        let pool = try DatabasePool(path: dir.appending(path: "coach.sqlite").path)
        return try AppDatabase(pool)
    }

    /// A throwaway database for tests and previews.
    static func inMemory() throws -> AppDatabase {
        try AppDatabase(DatabaseQueue())
    }

    private static var migrator: DatabaseMigrator {
        var migrator = DatabaseMigrator()

        migrator.registerMigration("v1") { db in
            // Timestamps are integer milliseconds since 1970 (see Date.epochMillis).
            try db.create(table: "fast") { t in
                t.primaryKey("id", .text)
                t.column("started_at", .integer).notNull()
                t.column("ended_at", .integer)
                t.column("goal_seconds", .integer).notNull()
                t.column("notes", .text).notNull().defaults(to: "")
                t.column("created_at", .integer).notNull()
                t.column("updated_at", .integer).notNull()
                t.column("deleted_at", .integer)
                t.column("origin", .text).notNull()
                t.column("server_seq", .integer)
            }
            try db.create(index: "fast_active", on: "fast", columns: ["ended_at", "deleted_at"])

            try db.create(table: "pending_change") { t in
                t.column("entity", .text).notNull()
                t.column("record_id", .text).notNull()
                t.primaryKey(["entity", "record_id"])
            }

            try db.create(table: "sync_state") { t in
                t.primaryKey("key", .text)
                t.column("value", .text).notNull()
            }
        }

        return migrator
    }
}

// MARK: - Sync bookkeeping

extension Database {
    /// Marks a record as changed locally so the next sync pushes it.
    func markPending(_ entity: String, id: String) throws {
        try execute(
            sql: "INSERT OR IGNORE INTO pending_change (entity, record_id) VALUES (?, ?)",
            arguments: [entity, id])
    }

    func clearPending(_ entity: String, id: String) throws {
        try execute(
            sql: "DELETE FROM pending_change WHERE entity = ? AND record_id = ?",
            arguments: [entity, id])
    }

    func pendingIDs(_ entity: String) throws -> [String] {
        try String.fetchAll(
            self, sql: "SELECT record_id FROM pending_change WHERE entity = ?",
            arguments: [entity])
    }

    func syncValue(_ key: String) throws -> String? {
        try String.fetchOne(self, sql: "SELECT value FROM sync_state WHERE key = ?", arguments: [key])
    }

    func setSyncValue(_ key: String, _ value: String) throws {
        try execute(
            sql: """
                INSERT INTO sync_state (key, value) VALUES (?, ?)
                ON CONFLICT (key) DO UPDATE SET value = excluded.value
                """,
            arguments: [key, value])
    }
}

import Foundation
import GRDB

/// One fasting period. `endedAt` is nil while it's running.
///
/// The same struct is the database row and the sync wire format; the coding
/// keys match the server's JSON field names.
struct Fast: Codable, Equatable, Identifiable, Sendable {
    static let entity = "fasts"

    var id: String
    var startedAt: Date
    var endedAt: Date?
    var goalSeconds: Int
    var notes: String
    var createdAt: Date
    var updatedAt: Date
    var deletedAt: Date?
    var origin: String
    var serverSeq: Int64?

    enum CodingKeys: String, CodingKey {
        case id, notes, origin
        case startedAt = "started_at"
        case endedAt = "ended_at"
        case goalSeconds = "goal_seconds"
        case createdAt = "created_at"
        case updatedAt = "updated_at"
        case deletedAt = "deleted_at"
        case serverSeq = "server_seq"
    }

    var isActive: Bool { endedAt == nil && deletedAt == nil }

    func elapsed(at now: Date) -> TimeInterval {
        (endedAt ?? now).timeIntervalSince(startedAt)
    }

    var goalDate: Date { startedAt.addingTimeInterval(TimeInterval(goalSeconds)) }
}

// Explicit row mapping so nil optionals are written as NULL on update.
extension Fast: FetchableRecord, PersistableRecord {
    static let databaseTableName = "fast"

    init(row: Row) throws {
        id = row["id"]
        startedAt = Date(epochMillis: row["started_at"])
        endedAt = (row["ended_at"] as Int64?).map(Date.init(epochMillis:))
        goalSeconds = row["goal_seconds"]
        notes = row["notes"]
        createdAt = Date(epochMillis: row["created_at"])
        updatedAt = Date(epochMillis: row["updated_at"])
        deletedAt = (row["deleted_at"] as Int64?).map(Date.init(epochMillis:))
        origin = row["origin"]
        serverSeq = row["server_seq"]
    }

    func encode(to container: inout PersistenceContainer) throws {
        container["id"] = id
        container["started_at"] = startedAt.epochMillis
        container["ended_at"] = endedAt?.epochMillis
        container["goal_seconds"] = goalSeconds
        container["notes"] = notes
        container["created_at"] = createdAt.epochMillis
        container["updated_at"] = updatedAt.epochMillis
        container["deleted_at"] = deletedAt?.epochMillis
        container["origin"] = origin
        container["server_seq"] = serverSeq
    }

    /// The running fast, if any.
    static func active(_ db: Database) throws -> Fast? {
        try Fast
            .filter(Column("ended_at") == nil && Column("deleted_at") == nil)
            .order(Column("started_at").desc)
            .fetchOne(db)
    }
}

extension Date {
    /// Now, at whole-millisecond precision. Every timestamp the app writes
    /// goes through this so it survives SQLite (integer ms), JSON (3 digits)
    /// and Postgres (µs) round trips exactly, which last-writer-wins
    /// comparisons rely on.
    static var nowMillis: Date { Date().truncatedToMillis }

    /// Rounds to the nearest millisecond. Rounding (not flooring) keeps this
    /// idempotent: k/1000 as a Double can sit just below k ms, and flooring
    /// it again would lose a millisecond.
    var truncatedToMillis: Date { Date(epochMillis: epochMillis) }

    var epochMillis: Int64 { Int64((timeIntervalSince1970 * 1000).rounded()) }

    init(epochMillis: Int64) {
        self.init(timeIntervalSince1970: Double(epochMillis) / 1000)
    }
}

import Foundation
import GRDB

enum FastError: LocalizedError {
    case alreadyActive
    case notFound

    var errorDescription: String? {
        switch self {
        case .alreadyActive: "A fast is already running."
        case .notFound: "That fast no longer exists."
        }
    }
}

/// Local writes for fasts. Every change bumps `updated_at` and queues the
/// record for the next push.
struct FastRepository: Sendable {
    let database: AppDatabase
    var origin = "phone"

    @discardableResult
    func start(goalSeconds: Int, at start: Date = .nowMillis) throws -> Fast {
        try database.writer.write { db in
            if try Fast.active(db) != nil { throw FastError.alreadyActive }
            let now = Date.nowMillis
            let fast = Fast(
                id: UUID().uuidString.lowercased(), startedAt: start.truncatedToMillis,
                endedAt: nil, goalSeconds: goalSeconds, notes: "",
                createdAt: now, updatedAt: now, deletedAt: nil, origin: origin, serverSeq: nil)
            try fast.insert(db)
            try db.markPending(Fast.entity, id: fast.id)
            return fast
        }
    }

    func end(_ id: String, at end: Date = .nowMillis) throws {
        try modify(id) { fast in
            fast.endedAt = max(end.truncatedToMillis, fast.startedAt)
        }
    }

    func setGoal(_ id: String, seconds: Int) throws {
        try modify(id) { $0.goalSeconds = seconds }
    }

    /// Soft delete: the tombstone syncs so other devices drop it too.
    func delete(_ id: String) throws {
        try modify(id) { $0.deletedAt = .nowMillis }
    }

    private func modify(_ id: String, _ change: @Sendable (inout Fast) -> Void) throws {
        try database.writer.write { db in
            guard var fast = try Fast.fetchOne(db, key: id) else { throw FastError.notFound }
            change(&fast)
            // Strictly newer, even within the same millisecond: the server
            // ignores pushes whose updated_at isn't greater than its copy.
            fast.updatedAt = max(Date.nowMillis, fast.updatedAt.addingTimeInterval(0.001))
            fast.origin = origin
            try fast.update(db)
            try db.markPending(Fast.entity, id: fast.id)
        }
    }
}

import Foundation
import GRDB

/// One sync pass: push queued local changes, then pull everything newer than
/// the stored cursor.
///
/// Conflicts resolve last-writer-wins on `updated_at`, the same rule the
/// server applies, so both sides converge on the same record.
struct SyncEngine: Sendable {
    let database: AppDatabase
    var pushBatchSize = 200
    var pullPageSize = 500

    struct Report: Equatable, Sendable {
        var pushed = 0
        var pulled = 0
    }

    private static let cursorKey = "cursor"

    func run(_ transport: some SyncTransport) async throws -> Report {
        var report = Report()
        report.pushed = try await push(transport)
        report.pulled = try await pull(transport)
        return report
    }

    private func push(_ transport: some SyncTransport) async throws -> Int {
        var total = 0
        // Bounded so a record that keeps changing can't loop forever.
        for _ in 0..<50 {
            let batch = try await database.writer.read { [pushBatchSize] db in
                let ids = Array(try db.pendingIDs(Fast.entity).prefix(pushBatchSize))
                return try Fast.filter(keys: ids).fetchAll(db)
            }
            if batch.isEmpty {
                // Drop queue entries whose record no longer exists.
                try await database.writer.write { db in
                    for id in try db.pendingIDs(Fast.entity) where try !Fast.exists(db, key: id) {
                        try db.clearPending(Fast.entity, id: id)
                    }
                }
                break
            }

            _ = try await transport.push(Changes(fasts: batch))
            total += batch.count

            // Applied and stale both leave the queue: a stale record means the
            // server has something newer, which the pull brings down. Only
            // clear entries the user hasn't edited again since we read them.
            try await database.writer.write { db in
                for sent in batch {
                    let current = try Fast.fetchOne(db, key: sent.id)
                    if current?.updatedAt == sent.updatedAt {
                        try db.clearPending(Fast.entity, id: sent.id)
                    }
                }
            }
            if batch.count < pushBatchSize { break }
        }
        return total
    }

    private func pull(_ transport: some SyncTransport) async throws -> Int {
        var total = 0
        var cursor = try await database.writer.read { db in
            try db.syncValue(Self.cursorKey).flatMap(Int64.init) ?? 0
        }
        while true {
            let page = try await transport.pull(since: cursor, limit: pullPageSize)
            try await database.writer.write { db in
                for remote in page.changes.fasts {
                    try Self.merge(remote, db)
                }
                try db.setSyncValue(Self.cursorKey, String(page.cursor))
            }
            total += page.changes.fasts.count
            cursor = page.cursor
            if !page.hasMore { break }
        }
        return total
    }

    private static func merge(_ remote: Fast, _ db: Database) throws {
        guard let local = try Fast.fetchOne(db, key: remote.id) else {
            try remote.insert(db)
            return
        }
        if local.updatedAt >= remote.updatedAt {
            // Ours is as new or newer; keep it (it's queued if it needs pushing).
            return
        }
        try remote.update(db)
        // A queued local edit that lost to a newer remote one shouldn't be pushed.
        try db.clearPending(Fast.entity, id: remote.id)
    }
}

import Foundation

/// Request and response bodies for the server's /v1/sync endpoints.
struct Changes: Codable, Equatable, Sendable {
    var fasts: [Fast] = []

    var isEmpty: Bool { fasts.isEmpty }
}

struct PushResult: Decodable, Sendable {
    var applied: [String]
    var stale: [String]
}

struct PullResult: Decodable, Sendable {
    var changes: Changes
    var cursor: Int64
    var hasMore: Bool

    enum CodingKeys: String, CodingKey {
        case changes, cursor
        case hasMore = "has_more"
    }
}

/// JSON coding matching the Go server: RFC 3339 timestamps. Go emits
/// anywhere from 0 to 9 fractional digits, so decoding parses the fraction by
/// hand; encoding always writes milliseconds.
enum Wire {
    static func encoder() -> JSONEncoder {
        let e = JSONEncoder()
        e.dateEncodingStrategy = .custom { date, encoder in
            var c = encoder.singleValueContainer()
            try c.encode(format(date))
        }
        return e
    }

    static func decoder() -> JSONDecoder {
        let d = JSONDecoder()
        d.dateDecodingStrategy = .custom { decoder in
            let c = try decoder.singleValueContainer()
            let s = try c.decode(String.self)
            guard let date = parse(s) else {
                throw DecodingError.dataCorruptedError(
                    in: c, debugDescription: "Invalid RFC 3339 timestamp: \(s)")
            }
            return date
        }
        return d
    }

    /// "2026-10-27T16:30:00.123Z", built from integer milliseconds so the
    /// fraction is exact.
    static func format(_ date: Date) -> String {
        let ms = date.epochMillis
        let seconds = ms >= 0 ? ms / 1000 : (ms - 999) / 1000
        let base = Date(timeIntervalSince1970: Double(seconds)).formatted(.iso8601) // "...:00Z"
        return String(base.dropLast()) + String(format: ".%03dZ", ms - seconds * 1000)
    }

    static func parse(_ s: String) -> Date? {
        // Split "2026-10-27T16:30:00.123456Z" into base, fraction and zone.
        guard let tIndex = s.firstIndex(of: "T"),
            let zoneStart = s[tIndex...].lastIndex(where: { $0 == "Z" || $0 == "+" || $0 == "-" })
        else { return nil }
        var head = String(s[..<zoneStart])
        let zone = String(s[zoneStart...])
        var digits = ""
        if let dot = head.firstIndex(of: ".") {
            digits = String(head[head.index(after: dot)...])
            guard !digits.isEmpty, digits.allSatisfy({ $0.isASCII && $0.isNumber }) else { return nil }
            head = String(head[..<dot])
        }
        guard let base = try? Date(head + zone, strategy: .iso8601) else { return nil }
        if digits.count <= 3 {
            // Whole milliseconds: build from integers so the result is exactly
            // what Date(epochMillis:) produces locally.
            let ms = Int64(digits.padding(toLength: 3, withPad: "0", startingAt: 0)) ?? 0
            return Date(epochMillis: base.epochMillis + ms)
        }
        return base.addingTimeInterval(Double("0." + digits) ?? 0)
    }
}

import Foundation

/// How the sync engine talks to the server. The HTTP implementation is below;
/// tests use a fake.
protocol SyncTransport: Sendable {
    func push(_ changes: Changes) async throws -> PushResult
    func pull(since cursor: Int64, limit: Int) async throws -> PullResult
}

enum SyncError: LocalizedError {
    case notConfigured
    case invalidURL
    case http(status: Int, message: String)
    case badResponse

    var errorDescription: String? {
        switch self {
        case .notConfigured: "Server address or token not set."
        case .invalidURL: "Server address isn't a valid https:// URL."
        case .http(let status, let message): "Server returned \(status): \(message)"
        case .badResponse: "Unexpected response from server."
        }
    }
}

struct HTTPTransport: SyncTransport {
    let baseURL: URL
    let token: String
    var session: URLSession = .shared

    init(config: ServerConfig, session: URLSession = .shared) throws {
        guard config.isComplete else { throw SyncError.notConfigured }
        guard let url = URL(string: config.url.trimmingCharacters(in: .whitespaces)),
            url.scheme == "https", url.host() != nil
        else { throw SyncError.invalidURL }
        self.baseURL = url
        self.token = config.token
        self.session = session
    }

    /// Checks reachability (no auth) and then the token (an empty pull page).
    func check() async throws {
        _ = try await send(URLRequest(url: baseURL.appending(path: "healthz")))
        _ = try await pull(since: Int64.max - 1, limit: 1)
    }

    func push(_ changes: Changes) async throws -> PushResult {
        var req = URLRequest(url: baseURL.appending(path: "v1/sync/push"))
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.httpBody = try Wire.encoder().encode(changes)
        return try await Wire.decoder().decode(PushResult.self, from: send(authorized(req)))
    }

    func pull(since cursor: Int64, limit: Int) async throws -> PullResult {
        let url = baseURL.appending(path: "v1/sync/pull").appending(queryItems: [
            URLQueryItem(name: "since", value: String(cursor)),
            URLQueryItem(name: "limit", value: String(limit)),
        ])
        return try await Wire.decoder().decode(PullResult.self, from: send(authorized(URLRequest(url: url))))
    }

    private func authorized(_ req: URLRequest) -> URLRequest {
        var req = req
        req.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        req.timeoutInterval = 20
        return req
    }

    private func send(_ req: URLRequest) async throws -> Data {
        let (data, response) = try await session.data(for: req)
        guard let http = response as? HTTPURLResponse else { throw SyncError.badResponse }
        guard http.statusCode == 200 else {
            let message = (try? JSONDecoder().decode([String: String].self, from: data))?["error"]
            throw SyncError.http(status: http.statusCode, message: message ?? "no details")
        }
        return data
    }
}

import Foundation
import Security

/// Where the server is and how to authenticate. The URL lives in
/// UserDefaults; the token lives in the Keychain.
struct ServerConfig: Equatable, Sendable {
    var url: String
    var token: String

    var isComplete: Bool {
        !url.trimmingCharacters(in: .whitespaces).isEmpty && !token.isEmpty
    }
}

struct ServerConfigStore: Sendable {
    private static let urlKey = "server.url"
    private static let keychainService = "dev.coach.api-token"

    func load() -> ServerConfig {
        ServerConfig(
            url: UserDefaults.standard.string(forKey: Self.urlKey) ?? "",
            token: Self.readToken() ?? "")
    }

    func save(_ config: ServerConfig) {
        UserDefaults.standard.set(config.url.trimmingCharacters(in: .whitespaces), forKey: Self.urlKey)
        Self.writeToken(config.token.trimmingCharacters(in: .whitespacesAndNewlines))
    }

    private static var baseQuery: [String: Any] {
        [kSecClass as String: kSecClassGenericPassword,
         kSecAttrService as String: keychainService]
    }

    private static func readToken() -> String? {
        var query = baseQuery
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne
        var item: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess,
            let data = item as? Data
        else { return nil }
        return String(data: data, encoding: .utf8)
    }

    private static func writeToken(_ token: String) {
        SecItemDelete(baseQuery as CFDictionary)
        guard !token.isEmpty else { return }
        var query = baseQuery
        query[kSecValueData as String] = Data(token.utf8)
        query[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlock
        SecItemAdd(query as CFDictionary, nil)
    }
}

